  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello लोकेश जी आपको car parking tension set की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "आपको कितने square feet चाहिए?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "Madam मुझे चाहिए गाड़ी के लिए कितना होगा वो देख लेंगे।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "गाड़ी की details नहीं देंगे।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "समझ गई पर एक approximate number बता दीजिए जैसे 500 square feet ताकि मैं सही seller से connect कर सकूं।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "मतलब दो square feet का लगभग।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "क्या आपको दो square feet चाहिए?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "दो सौ दो सौ।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "अब parking capacity के बारे में बात कर लेते हैं।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपको 2 cars या 3 cars के लिए चाहिए या कुछ और?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "दो car के लिए।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "अब बताइए width में क्या prefer करेंगे?"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "20 feet, 8 feet या कोई और?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "कितना piece बोले?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "नहीं आपने बिल्कुल सही बोला।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "बस width बता दीजिए कि आपको 20 feet, 8 feet या कुछ और चाहिए?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "twenty feet होगा something."
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "ये आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 25,
      "speaker": "caller",
      "text": "ठीक है Ma'am।"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
